-- Correct the YTD tax reference introduced in the validation-gate rebuild.
-- YTD net income must use YTD tax, not the selected-period tax.

create or replace function public.get_financial_statements(p_organization_id uuid,p_period_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $function$
declare
  v_period record; v_fiscal_month smallint; v_fiscal_year_start date;
  v_income jsonb; v_income_ytd jsonb; v_balance jsonb; v_validation jsonb;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if not (public.has_org_permission(p_organization_id,'screen.financial_statements.view') or public.has_org_permission(p_organization_id,'statements.view') or public.has_org_permission(p_organization_id,'view')) then raise exception 'Financial statements view permission required'; end if;
  select fp.id,fp.organization_id,fp.period_start,fp.period_end,fp.status,o.fiscal_year_start_month into v_period from public.financial_periods fp join public.organizations o on o.id=fp.organization_id where fp.id=p_period_id and fp.organization_id=p_organization_id;
  if v_period.id is null then raise exception 'Financial period not found'; end if;
  v_fiscal_month:=greatest(1,least(12,v_period.fiscal_year_start_month));
  v_fiscal_year_start:=make_date(extract(year from v_period.period_start)::integer-case when extract(month from v_period.period_start)::integer<v_fiscal_month then 1 else 0 end,v_fiscal_month,1);
  with scoped_facts as (select f.* from public.financial_facts f where f.organization_id=p_organization_id and f.fact_type='actual' and f.status='published' and public.has_org_data_scope(f.organization_id,'legal_entity',f.legal_entity_id) and public.has_org_data_scope(f.organization_id,'branch',f.branch_id) and public.has_org_data_scope(f.organization_id,'department',f.department_id) and public.has_org_data_scope(f.organization_id,'cost_center',f.cost_center_id) and public.has_org_data_scope(f.organization_id,'region',f.region_id) and public.has_org_data_scope(f.organization_id,'product',f.product_id) and public.has_org_data_scope(f.organization_id,'project',f.project_id)), classified as (select f.financial_period_id,fp.period_start,fp.period_end,a.id account_id,a.code,a.name,a.account_type,a.statement_type,a.statement_section,a.statement_subclassification,coalesce(f.debit_minor,0)::bigint debit_minor,coalesce(f.credit_minor,0)::bigint credit_minor from scoped_facts f join public.financial_periods fp on fp.id=f.financial_period_id and fp.organization_id=p_organization_id join public.accounts a on a.id=f.account_id and a.organization_id=p_organization_id), period_income as (select coalesce(sum(case when statement_subclassification='revenue' then credit_minor-debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when statement_subclassification='cogs' then debit_minor-credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when statement_subclassification='operating_expense' then debit_minor-credit_minor else 0 end),0)::bigint operating_expenses,coalesce(sum(case when statement_subclassification='other_income' then credit_minor-debit_minor else 0 end),0)::bigint other_income,coalesce(sum(case when statement_subclassification='depreciation_amortization' then debit_minor-credit_minor else 0 end),0)::bigint depreciation_amortization,coalesce(sum(case when statement_subclassification='finance_cost' then debit_minor-credit_minor else 0 end),0)::bigint finance_cost,coalesce(sum(case when statement_subclassification='tax' then debit_minor-credit_minor else 0 end),0)::bigint tax,coalesce(sum(case when statement_subclassification='other_expense' then debit_minor-credit_minor else 0 end),0)::bigint other_expenses,count(distinct account_id) filter(where lower(coalesce(statement_type,''))='income_statement' and statement_subclassification is null)::integer unclassified_count from classified where financial_period_id=p_period_id), ytd_income as (select coalesce(sum(case when statement_subclassification='revenue' then credit_minor-debit_minor else 0 end),0)::bigint revenue,coalesce(sum(case when statement_subclassification='cogs' then debit_minor-credit_minor else 0 end),0)::bigint cogs,coalesce(sum(case when statement_subclassification='operating_expense' then debit_minor-credit_minor else 0 end),0)::bigint operating_expenses,coalesce(sum(case when statement_subclassification='other_income' then credit_minor-debit_minor else 0 end),0)::bigint other_income,coalesce(sum(case when statement_subclassification='depreciation_amortization' then debit_minor-credit_minor else 0 end),0)::bigint depreciation_amortization,coalesce(sum(case when statement_subclassification='finance_cost' then debit_minor-credit_minor else 0 end),0)::bigint finance_cost,coalesce(sum(case when statement_subclassification='tax' then debit_minor-credit_minor else 0 end),0)::bigint tax,coalesce(sum(case when statement_subclassification='other_expense' then debit_minor-credit_minor else 0 end),0)::bigint other_expenses from classified where period_start>=v_fiscal_year_start and period_end<=v_period.period_end), balance_accounts as (select a.code,a.name,a.statement_section,a.account_type,a.statement_subclassification,coalesce(sum(f.debit_minor),0)::bigint debit,coalesce(sum(f.credit_minor),0)::bigint credit,coalesce(sum(f.debit_minor-f.credit_minor),0)::bigint balance from public.accounts a left join classified f on f.account_id=a.id and f.period_end<=v_period.period_end where a.organization_id=p_organization_id and lower(coalesce(a.statement_type,''))='balance_sheet' and a.statement_subclassification in ('asset','liability','equity') group by a.code,a.name,a.statement_section,a.account_type,a.statement_subclassification), totals as (select coalesce(sum(case when statement_subclassification='asset' then balance else 0 end),0)::bigint assets,coalesce(sum(case when statement_subclassification='liability' then -balance else 0 end),0)::bigint liabilities,coalesce(sum(case when statement_subclassification='equity' then -balance else 0 end),0)::bigint equity from balance_accounts)
  select jsonb_build_object('revenue',pi.revenue,'cogs',pi.cogs,'gross_profit',pi.revenue-pi.cogs,'operating_expenses',pi.operating_expenses,'other_income',pi.other_income,'depreciation_amortization',pi.depreciation_amortization,'ebitda',pi.revenue-pi.cogs-pi.operating_expenses+pi.other_income,'ebit',pi.revenue-pi.cogs-pi.operating_expenses+pi.other_income-pi.depreciation_amortization,'finance_cost',pi.finance_cost,'other_expenses',pi.other_expenses,'ebt',pi.revenue-pi.cogs-pi.operating_expenses+pi.other_income-pi.depreciation_amortization-pi.finance_cost-pi.other_expenses,'tax',pi.tax,'net_income',pi.revenue-pi.cogs-pi.operating_expenses+pi.other_income-pi.depreciation_amortization-pi.finance_cost-pi.other_expenses-pi.tax,'unclassified_income_accounts',pi.unclassified_count) into v_income from period_income pi;
  select jsonb_build_object('revenue',yi.revenue,'cogs',yi.cogs,'gross_profit',yi.revenue-yi.cogs,'operating_expenses',yi.operating_expenses,'other_income',yi.other_income,'depreciation_amortization',yi.depreciation_amortization,'ebitda',yi.revenue-yi.cogs-yi.operating_expenses+yi.other_income,'ebit',yi.revenue-yi.cogs-yi.operating_expenses+yi.other_income-yi.depreciation_amortization,'finance_cost',yi.finance_cost,'other_expenses',yi.other_expenses,'ebt',yi.revenue-yi.cogs-yi.operating_expenses+yi.other_income-yi.depreciation_amortization-yi.finance_cost-yi.other_expenses,'tax',yi.tax,'net_income',yi.revenue-yi.cogs-yi.operating_expenses+yi.other_income-yi.depreciation_amortization-yi.finance_cost-yi.other_expenses-yi.tax) into v_income_ytd from ytd_income yi;
  select jsonb_build_object('accounts',coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'section',statement_section,'account_type',account_type,'subclassification',statement_subclassification,'debit',debit,'credit',credit,'balance',balance) order by code) from balance_accounts),'[]'::jsonb),'total_assets',t.assets,'total_liabilities',t.liabilities,'total_equity',t.equity,'current_period_net_income',(v_income->>'net_income')::bigint,'ytd_net_income',(v_income_ytd->>'net_income')::bigint,'balance_check',t.assets-t.liabilities-t.equity-(v_income_ytd->>'net_income')::bigint) into v_balance from totals t;
  select jsonb_build_object('unclassified_income_accounts',coalesce((v_income->>'unclassified_income_accounts')::integer,0),'balance_sheet_difference',coalesce((v_balance->>'balance_check')::bigint,0)) into v_validation;
  return jsonb_build_object('period',jsonb_build_object('id',v_period.id,'start',v_period.period_start,'end',v_period.period_end,'status',v_period.status),'fiscal_year_start',v_fiscal_year_start,'income_statement',v_income,'income_statement_ytd',v_income_ytd,'balance_sheet',v_balance,'validation',v_validation,'methodology',jsonb_build_object('actuals_only',true,'published_only',true,'balance_sheet_cumulative',true,'income_statement_basis','selected_period','income_statement_ytd_available',true,'fiscal_year_aware',true,'classification_authoritative',true));
end;
$function$;
revoke all on function public.get_financial_statements(uuid,uuid) from public,anon;
grant execute on function public.get_financial_statements(uuid,uuid) to authenticated;
